describe('User Profile Picture Upload', () => {
  const testImagePath = 'cypress/fixtures/profile-picture.jpg';
  const profilePictureSelector = '[data-testid="profile-picture"]';
  const uploadInputSelector = 'input[type="file"]';
  const previewImageSelector = '[data-testid="picture-preview"]';
  const uploadButtonSelector = '[data-testid="upload-button"]';
  const errorMessageSelector = '[data-testid="error-message"]';

  beforeEach(() => {
    cy.visit('/profile');
    cy.get(profilePictureSelector).should('be.visible');
  });

  it('should upload a profile picture and display preview', () => {
    // Verify upload input exists
    cy.get(uploadInputSelector).should('exist');

    // Upload the image file
    cy.get(uploadInputSelector).selectFile(testImagePath, { force: true });

    // Verify preview image appears
    cy.get(previewImageSelector).should('be.visible');
    cy.get(previewImageSelector).should('have.attr', 'src').and('include', 'blob:');

    // Click upload button to confirm
    cy.get(uploadButtonSelector).click();

    // Verify success message or confirmation
    cy.get('[data-testid="success-message"]').should('contain', 'Profile picture updated successfully');

    // Verify the profile picture is updated
    cy.get(profilePictureSelector).should('have.attr', 'src').and('not.be.empty');
  });

  it('should display preview immediately after file selection without upload confirmation', () => {
    // Select file
    cy.get(uploadInputSelector).selectFile(testImagePath, { force: true });

    // Verify preview appears immediately
    cy.get(previewImageSelector).should('be.visible');
    cy.get(previewImageSelector).should('have.css', 'display', 'block');

    // Verify preview image has valid src
    cy.get(previewImageSelector).invoke('attr', 'src').should('match', /^blob:/);

    // Verify preview dimensions are reasonable
    cy.get(previewImageSelector).should('have.css', 'width').and('not.equal', '0px');
    cy.get(previewImageSelector).should('have.css', 'height').and('not.equal', '0px');
  });

  it('should handle invalid file type gracefully', () => {
    // Attempt to upload invalid file type
    cy.get(uploadInputSelector).selectFile('cypress/fixtures/invalid-file.txt', { force: true });

    // Verify error message is displayed
    cy.get(errorMessageSelector).should('be.visible');
    cy.get(errorMessageSelector).should('contain', 'Please upload a valid image file');

    // Verify preview is not shown
    cy.get(previewImageSelector).should('not.exist');

    // Verify original profile picture remains unchanged
    cy.get(profilePictureSelector).should('be.visible');
  });

  it('should handle file size exceeding limit', () => {
    // Create a large file mock
    const largeFile = new File(['x'.repeat(10 * 1024 * 1024)], 'large-image.jpg', { type: 'image/jpeg' });

    // Attempt to upload large file
    cy.get(uploadInputSelector).selectFile({ contents: Cypress.Buffer.from('x'.repeat(10 * 1024 * 1024)), fileName: 'large-image.jpg' }, { force: true });

    // Verify error message for file size
    cy.get(errorMessageSelector).should('be.visible');
    cy.get(errorMessageSelector).should('contain', 'File size must be less than');

    // Verify preview is not displayed
    cy.get(previewImageSelector).should('not.exist');
  });

  it('should allow replacing an existing profile picture', () => {
    // Upload first image
    cy.get(uploadInputSelector).selectFile(testImagePath, { force: true });
    cy.get(previewImageSelector).should('be.visible');
    cy.get(uploadButtonSelector).click();
    cy.get('[data-testid="success-message"]').should('be.visible');

    // Get first image src
    cy.get(profilePictureSelector).invoke('attr', 'src').then((firstImageSrc) => {
      // Upload second image
      cy.get(uploadInputSelector).selectFile('cypress/fixtures/profile-picture-2.jpg', { force: true });
      cy.get(previewImageSelector).should('be.visible');
      cy.get(uploadButtonSelector).click();

      // Verify image has changed
      cy.get(profilePictureSelector).invoke('attr', 'src').should('not.equal', firstImageSrc);
      cy.get('[data-testid="success-message"]').should('contain', 'Profile picture updated successfully');
    });
  });

  it('should cancel upload and maintain previous picture', () => {
    // Get current profile picture src
    cy.get(profilePictureSelector).invoke('attr', 'src').then((originalSrc) => {
      // Select a file
      cy.get(uploadInputSelector).selectFile(testImagePath, { force: true });
      cy.get(previewImageSelector).should('be.visible');

      // Click cancel button
      cy.get('[data-testid="cancel-button"]').click();

      // Verify preview is hidden
      cy.get(previewImageSelector).should('not.be.visible');

      // Verify profile picture remains unchanged
      cy.get(profilePictureSelector).invoke('attr', 'src').should('equal', originalSrc);
    });
  });
});
